<script lang="ts">
  // Selfbound logo as inline SVG in currentColor: follows light and dark mode. Shapes from
  // lib/brand.ts (generated by tooling/brand.mjs from brand/*.svg).
  import { BRAND } from '../lib/brand.ts';

  let { kind = 'symbol', height = 20, label = 'Selfbound' }: { kind?: 'symbol' | 'wordmark' | 'lockup'; height?: number; label?: string | null } = $props();
  const shape = $derived(BRAND[kind]);
</script>

<svg
  class="logo logo-{kind}"
  viewBox={shape.viewBox}
  width={Math.round(height * shape.ratio * 100) / 100}
  {height}
  fill="currentColor"
  fill-rule={shape.rule}
  role={label ? 'img' : undefined}
  aria-label={label}
  aria-hidden={label ? undefined : 'true'}
  focusable="false"
>{#each shape.paths as p}<path d={p.d} transform={'transform' in p ? p.transform : undefined} />{/each}</svg>
